WITH f AS (SELECT * FROM `ent-kixavvik-dev.disruptions.togvarsel_features` WHERE weekday AND NOT holiday AND am_n > 300 AND pm_n > 300)
SELECT 'am_t10' m, COUNT(*) n, ROUND(AVG(am_t10),3) mean, ROUND(APPROX_QUANTILES(am_t10,20)[OFFSET(10)],3) p50, ROUND(APPROX_QUANTILES(am_t10,20)[OFFSET(15)],3) p75, ROUND(APPROX_QUANTILES(am_t10,20)[OFFSET(17)],3) p85, ROUND(APPROX_QUANTILES(am_t10,20)[OFFSET(18)],3) p90, ROUND(APPROX_QUANTILES(am_t10,20)[OFFSET(19)],3) p95,
  COUNTIF(am_t10>=0.10) ge10, COUNTIF(am_t10>=0.15) ge15, COUNTIF(am_t10>=0.20) ge20, COUNTIF(am_bad) t5bad, COUNTIF(am_bad AND am_t10>=0.15) both15, ROUND(CORR(am_t5, am_t10),3) corr_t5
FROM f
UNION ALL
SELECT 'pm_t10', COUNT(*), ROUND(AVG(pm_t10),3), ROUND(APPROX_QUANTILES(pm_t10,20)[OFFSET(10)],3), ROUND(APPROX_QUANTILES(pm_t10,20)[OFFSET(15)],3), ROUND(APPROX_QUANTILES(pm_t10,20)[OFFSET(17)],3), ROUND(APPROX_QUANTILES(pm_t10,20)[OFFSET(18)],3), ROUND(APPROX_QUANTILES(pm_t10,20)[OFFSET(19)],3),
  COUNTIF(pm_t10>=0.10), COUNTIF(pm_t10>=0.15), COUNTIF(pm_t10>=0.20), COUNTIF(pm_bad), COUNTIF(pm_bad AND pm_t10>=0.15), ROUND(CORR(pm_t5, pm_t10),3)
FROM f
UNION ALL
SELECT 'am_cancel', COUNT(*), ROUND(AVG(am_cancel),3), ROUND(APPROX_QUANTILES(am_cancel,20)[OFFSET(10)],3), ROUND(APPROX_QUANTILES(am_cancel,20)[OFFSET(15)],3), ROUND(APPROX_QUANTILES(am_cancel,20)[OFFSET(17)],3), ROUND(APPROX_QUANTILES(am_cancel,20)[OFFSET(18)],3), ROUND(APPROX_QUANTILES(am_cancel,20)[OFFSET(19)],3),
  COUNTIF(am_cancel>=0.10), COUNTIF(am_cancel>=0.15), COUNTIF(am_cancel>=0.20), COUNTIF(am_bad), COUNTIF(am_bad AND am_cancel>=0.05), ROUND(CORR(am_t5, am_cancel),3)
FROM f
UNION ALL
SELECT 'pm_cancel', COUNT(*), ROUND(AVG(pm_cancel),3), ROUND(APPROX_QUANTILES(pm_cancel,20)[OFFSET(10)],3), ROUND(APPROX_QUANTILES(pm_cancel,20)[OFFSET(15)],3), ROUND(APPROX_QUANTILES(pm_cancel,20)[OFFSET(17)],3), ROUND(APPROX_QUANTILES(pm_cancel,20)[OFFSET(18)],3), ROUND(APPROX_QUANTILES(pm_cancel,20)[OFFSET(19)],3),
  COUNTIF(pm_cancel>=0.10), COUNTIF(pm_cancel>=0.15), COUNTIF(pm_cancel>=0.20), COUNTIF(pm_bad), COUNTIF(pm_bad AND pm_cancel>=0.05), ROUND(CORR(pm_t5, pm_cancel),3)
FROM f
